using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text.Json;
using System.Windows;
using System.Windows.Documents;
using System.Windows.Media;
using System.Windows.Media.Imaging;

namespace StickyNotes;
internal static class SelfTests {
 public static int Run(string[] args){string root=Path.Combine(Path.GetTempPath(),"WindowsStickyNotes-tests-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);var results=new List<object>();int failures=0;
  void Check(string name,Action action){try{action();results.Add(new{name,passed=true});}catch(Exception e){failures++;results.Add(new{name,passed=false,error=e.ToString()});}}
  void Assert(bool ok,string why){if(!ok)throw new Exception(why);}
  var app=(NotesApp)Application.Current;app.Store=new Store(root);app.DataRoot=root;Note? note=null;
  Check("Physical work areas convert correctly before first Show at common DPI scales",()=>{foreach(uint dpi in new uint[]{96,120,144,192,216}){var matrix=DisplayDpi.FromDpi(dpi);var point=matrix.Transform(new Point(-1920,2160));var size=matrix.Transform(new Vector(5120,2088));Assert(Math.Abs(point.X-(-1920d*96/dpi))<.001&&Math.Abs(point.Y-2160d*96/dpi)<.001&&Math.Abs(size.X-5120d*96/dpi)<.001&&Math.Abs(size.Y-2088d*96/dpi)<.001,"Incorrect native pixel to DIP conversion");}Assert(DisplayDpi.FromDpi(0).IsIdentity,"Unknown DPI fallback failed");});
  bool ValidLayout(Rect work,IReadOnlyList<Rect> plan)=>plan.All(work.Contains)&&plan.SelectMany((a,i)=>plan.Skip(i+1).Select(b=>Rect.Intersect(a,b))).All(r=>r.IsEmpty||r.Width==0||r.Height==0);
  Check("Auto-arrange preserves different heights and stacks at the right of a portrait monitor",()=>{var work=new Rect(-1080,120,1080,1920);var sizes=new[]{new Size(344,520),new Size(344,300),new Size(344,300),new Size(344,260)};var p=NoteArrangement.Plan(work,sizes)!;Assert(p.Count==4&&ValidLayout(work,p)&&p.All(r=>Math.Abs(r.Right-(work.Right-12))<.001),"Not a right-aligned column");Assert(p.Select(r=>r.Height).SequenceEqual(sizes.Select(s=>s.Height)),"Heights changed without need");for(int i=1;i<p.Count;i++)Assert(Math.Abs(p[i].Top-p[i-1].Bottom-NoteArrangement.Gap)<.001,"Uneven vertical gap");});
  Check("Auto-arrange keeps the visible card gap compact",()=>Assert(NoteArrangement.Gap+2*NoteWindow.CardMargin<=10,"Visible gap includes excess transparent margins"));
  Check("Auto-arrange opens columns to the left and keeps all notes inside a landscape monitor",()=>{var work=new Rect(1920,-300,1920,1040);var p=NoteArrangement.Plan(work,Enumerable.Repeat(new Size(344,380),4).ToArray())!;Assert(p.Count==4&&ValidLayout(work,p)&&p.Select(r=>r.Left).Distinct().Count()==2,"Columns overlap or leave work area");Assert(p[0].Left>p[3].Left&&p.Select(r=>r.Width).Distinct().Count()==1,"Wrong column direction or widths");});
  Check("Auto-arrange fits dense notes without violating minimum size",()=>{var work=new Rect(0,0,1280,720);var p=NoteArrangement.Plan(work,Enumerable.Repeat(new Size(420,700),6).ToArray())!;Assert(p.Count==6&&ValidLayout(work,p)&&p.All(r=>r.Width>=300&&r.Height>=260),"Dense arrangement does not fit");});
  Check("Auto-arrange refuses overflow instead of stacking notes on top of each other",()=>Assert(NoteArrangement.Plan(new Rect(0,0,800,600),Enumerable.Repeat(new Size(344,380),7).ToArray())==null,"Overflow was accepted"));
  Check("Auto-arrange supports tiny work areas and an empty desktop",()=>{var work=new Rect(-240,-240,240,240);var p=NoteArrangement.Plan(work,new[]{new Size(344,380)})!;Assert(ValidLayout(work,p)&&p.Count==1&&p[0].Size==work.Size,"Tiny work area escaped");Assert(NoteArrangement.Plan(work,Array.Empty<Size>())!.Count==0,"Empty area failed");});
  Check("Auto-arrange is stable when repeated",()=>{var work=new Rect(0,0,1366,768);var a=NoteArrangement.Plan(work,Enumerable.Repeat(new Size(344,600),6).ToArray())!;var b=NoteArrangement.Plan(work,a.Select(r=>r.Size).ToArray())!;Assert(a.Zip(b).All(pair=>Math.Abs(pair.First.X-pair.Second.X)<.001&&Math.Abs(pair.First.Y-pair.Second.Y)<.001&&Math.Abs(pair.First.Height-pair.Second.Height)<.001),"Repeated arrangement moves or shrinks notes again");});
  Check("Background opacity defaults to 100 for old notebooks, persists and stays within range",()=>{string path=Path.Combine(root,"opacity");var s=new Store(path);Assert(s.Book.BackgroundOpacity==100,"New notebook is not opaque");s.Save();var file=Path.Combine(path,"notebook.json");var json=System.Text.Json.Nodes.JsonNode.Parse(File.ReadAllText(file))!;json.AsObject().Remove("BackgroundOpacity");File.WriteAllText(file,json.ToJsonString());s=new Store(path);Assert(s.Book.BackgroundOpacity==100,"Existing notebook is not opaque");s.Book.BackgroundOpacity=35;s.Save();Assert(new Store(path).Book.BackgroundOpacity==35,"Preference did not persist");s.Book.BackgroundOpacity=-5;Assert(s.Book.BackgroundOpacity==0,"Negative opacity accepted");s.Book.BackgroundOpacity=150;Assert(s.Book.BackgroundOpacity==100,"Opacity above 100 accepted");});
  Check("Automatic colors: first 32 unique",()=>Assert(Enumerable.Range(0,32).Select(Store.NextColor).Distinct().Count()==32,"Repeated automatic color"));
  Check("New color also avoids manually chosen colors",()=>{var colors=new Store(Path.Combine(root,"colors"));var a=colors.Create();a.Color=Store.Palette[1];colors.Save();var b=colors.Create();Assert(a.Color!=b.Color,"Manual color was repeated");});
  Check("New notes show distinct actual colors in both themes beyond fifty notes",()=>{var colors=new Store(Path.Combine(root,"automatic-visible-colors"));var notes=Enumerable.Range(0,64).Select(_=>colors.Create()).ToArray();foreach(bool dark in new[]{true,false}){var surfaces=notes.Select(n=>NoteColors.Surface(n.Color,n.ColorMode,dark)).ToArray();Assert(surfaces.Distinct().Count()==notes.Length,"New notes share a visible color");Assert(notes.All(n=>NoteColors.Surface(n.Color,n.ColorMode,dark)==(Color)ColorConverter.ConvertFromString(n.Color)),"New note color is muted");}});
  Check("Automatic colors avoid existing notes across areas after restart and sequence reset",()=>{string dir=Path.Combine(root,"automatic-color-restart");var colors=new Store(dir);var existing=colors.Create();existing.Color=Store.Palette[1].ToLowerInvariant();existing.ColorMode="Neon";colors.Book.Areas.Add("Outra área");colors.Book.ActiveArea="Outra área";colors.Book.ColorSequence=0;colors.Save();var reopened=new Store(dir);var created=reopened.Create();Assert(!string.Equals(created.Color,existing.Color,StringComparison.OrdinalIgnoreCase),"Existing color in another area repeated");Assert(created.ColorMode=="Pastel"&&created.Area=="Outra área","New note appearance or area incorrect");var persisted=new Store(dir).Book.Notes.Single(n=>n.Id==created.Id);Assert(persisted.Color==created.Color&&persisted.ColorMode==created.ColorMode,"Automatic appearance did not persist");});
  Check("Vivid and neon colors remain saturated with readable text in both themes",()=>{foreach(string mode in new[]{"Soft","Normal","Pastel","Vivid","Neon","Earth"})foreach(bool dark in new[]{true,false})foreach(string hex in NoteColors.Palette(mode)){var background=NoteColors.Surface(hex,mode,dark);Assert(NoteColors.Contrast(background,NoteColors.Text(background))>=4.5,"Unreadable color: "+hex);if(mode!="Soft")Assert(background==(Color)ColorConverter.ConvertFromString(hex),"Strong color was muted");}});
  Check("Color selector provides 50 unique presets in five rows of ten",()=>{var rows=NoteColors.Rows;Assert(rows.Length==5&&rows.All(r=>r.Colors.Length==10)&&rows.SelectMany(r=>r.Colors).Distinct(StringComparer.OrdinalIgnoreCase).Count()==50,"Palette count or organization is incorrect");});
  Check("Legacy notes retain soft appearance and their saved color",()=>{string dir=Path.Combine(root,"legacy");var old=new Store(dir);var n=old.Create();n.Color="#EDAFC5";old.Save();string path=Path.Combine(dir,"notebook.json");var json=System.Text.Json.Nodes.JsonNode.Parse(File.ReadAllText(path))!;json["Notes"]![0]!.AsObject().Remove("ColorMode");File.WriteAllText(path,json.ToJsonString());var loaded=new Store(dir).Book.Notes.Single();Assert(loaded.ColorMode=="Soft"&&loaded.Color=="#EDAFC5","Legacy appearance changed");});
  Check("Create, title, area and position persist",()=>{note=app.Store.Create();note.Title="Teste com acentuação — ideia";note.Left=-120;note.Top=72;app.Store.Book.Areas.Add("Projetos");note.Area="Projetos";app.Store.Book.WidgetPinned=true;app.Store.Save();var s=new Store(root);var n=s.Book.Notes.Single();Assert(n.Title==note.Title&&n.Left==-120&&n.Area=="Projetos"&&s.Book.WidgetPinned,"Metadata did not round-trip");});
  NoteWindow? window=null;
  Check("Note editors use a transparent template independent of Fluent input states",()=>{var w=new NoteWindow(app,note!);Assert(w.Editor.ReadLocalValue(System.Windows.Controls.Control.TemplateProperty)!=DependencyProperty.UnsetValue&&w.TitleBox.ReadLocalValue(System.Windows.Controls.Control.TemplateProperty)!=DependencyProperty.UnsetValue,"Note editors inherit the filled Fluent input template");});
  Check("Imported document backgrounds clear without losing rich text",()=>{var w=new NoteWindow(app,note!);var run=new Run("Texto preservado"){Background=Brushes.Red,FontWeight=FontWeights.Bold};var paragraph=new Paragraph(run){Background=Brushes.Blue};var cell=new TableCell(paragraph){Background=Brushes.Green};var row=new TableRow();row.Cells.Add(cell);var group=new TableRowGroup();group.Rows.Add(row);var table=new Table{Background=Brushes.Yellow};table.RowGroups.Add(group);w.Editor.Document=new FlowDocument(table){Background=Brushes.Black};w.ApplyColor();Assert(new[]{w.Editor.Document.Background,table.Background,cell.Background,paragraph.Background,run.Background}.All(b=>b==null||b is SolidColorBrush solid&&solid.Color.A==0),"Imported background covers the note color");Assert(run.Text=="Texto preservado"&&run.FontWeight==FontWeights.Bold,"Formatting or text changed");});
  Check("Rich paste and reopened notes keep the note background and formatting",()=>{var w=new NoteWindow(app,note!);using var input=new MemoryStream(System.Text.Encoding.UTF8.GetBytes("<Section xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' Background='Red'><Paragraph Background='Blue'><Bold Background='Green'>Colado com formato</Bold></Paragraph></Section>"));new TextRange(w.Editor.Document.ContentStart,w.Editor.Document.ContentEnd).Load(input,DataFormats.Xaml);Assert(w.Save(),"Pasted document did not save");var reopened=new NoteWindow(app,note!);var text=new TextRange(reopened.Editor.Document.ContentStart,reopened.Editor.Document.ContentEnd);Assert(text.Text.Contains("Colado com formato"),"Pasted text lost");var xaml=new MemoryStream();text.Save(xaml,DataFormats.Xaml);var saved=System.Text.Encoding.UTF8.GetString(xaml.ToArray());Assert(!saved.Contains("#FFFF0000")&&!saved.Contains("#FF0000FF")&&!saved.Contains("#FF008000")&&saved.Contains("Bold"),"Background or formatting incorrect after reopen");});
  Check("Native rich text and embedded image survive reopen",()=>{window=new NoteWindow(app,note!);window.Editor.Document.Blocks.Add(new Paragraph(new Bold(new Run("Texto salvo com imagem"))));byte[] pixels=Enumerable.Repeat((byte)255,80*40*4).ToArray();window.InsertImage(BitmapSource.Create(80,40,96,96,PixelFormats.Bgra32,null,pixels,320));Assert(window.Save(),"Save failed");var doc=new FlowDocument();app.Store.LoadDocument(note!,doc);Assert(new TextRange(doc.ContentStart,doc.ContentEnd).Text.Contains("Texto salvo com imagem"),"Text missing");var block=doc.Blocks.OfType<BlockUIContainer>().Single();Assert(block.Child is System.Windows.Controls.Image im&&im.Source is BitmapSource bm&&bm.PixelWidth==80&&bm.PixelHeight==40,"Embedded image missing: "+(block.Child is System.Windows.Controls.Image img?img.Source?.ToString():block.Child?.GetType().Name));});
  Check("Moving notes between areas preserves text and embedded images",()=>{var bytes=File.ReadAllBytes(app.Store.DocumentPath(note!));app.MoveNoteToArea(note!,"Minha mesa");Assert(new Store(root).Book.Notes.Single().Area=="Minha mesa"&&bytes.SequenceEqual(File.ReadAllBytes(app.Store.DocumentPath(note!))),"Moving an area changed the document");app.MoveNoteToArea(note!,"Projetos");});
  Check("Color, pin, resized window and no taskbar entry",()=>{window!.TitleBox.Text="Título editado";note!.Color="#A6CDEE";note.Pinned=true;window.ApplyColor();window.Width=410;window.Height=420;window.MarkDirty();Assert(window.Save(),"Save failed");Assert(!window.ShowInTaskbar,"Unexpected taskbar entry");Assert(new Store(root).Book.Notes.Single().Color=="#A6CDEE","Color not persisted");});
  Check("Images insert at the caret inside lists, sections and table cells and survive reopen",()=>{var originalStore=app.Store;app.Store=new Store(Path.Combine(root,"nested-image"));try{foreach(string kind in new[]{"list","section","table"}){var item=app.Store.Create();var w=new NoteWindow(app,item);w.Editor.Document.Blocks.Clear();var paragraph=new Paragraph(new Bold(new Run("Preserved "+kind)));BlockCollection blocks;if(kind=="list"){var li=new ListItem(paragraph);w.Editor.Document.Blocks.Add(new System.Windows.Documents.List(li));blocks=li.Blocks;}else if(kind=="section"){var section=new Section(paragraph);w.Editor.Document.Blocks.Add(section);blocks=section.Blocks;}else{var cell=new TableCell(paragraph);var row=new TableRow();row.Cells.Add(cell);var group=new TableRowGroup();group.Rows.Add(row);var table=new Table();table.RowGroups.Add(group);w.Editor.Document.Blocks.Add(table);blocks=cell.Blocks;}w.Editor.CaretPosition=paragraph.ContentEnd;w.InsertImage(BitmapSource.Create(8,8,96,96,PixelFormats.Bgra32,null,new byte[256],32));Assert(blocks.Count==3&&blocks.OfType<BlockUIContainer>().Count()==1,"Image escaped caret container");Assert(w.Save(),"Nested image save failed");var reopened=new FlowDocument();app.Store.LoadDocument(item,reopened);Assert(new TextRange(reopened.ContentStart,reopened.ContentEnd).Text.Contains("Preserved "+kind),"Nested text lost");BlockCollection loaded=kind=="list"?reopened.Blocks.OfType<System.Windows.Documents.List>().Single().ListItems.FirstListItem.Blocks:kind=="section"?reopened.Blocks.OfType<Section>().Single().Blocks:reopened.Blocks.OfType<Table>().Single().RowGroups[0].Rows[0].Cells[0].Blocks;Assert(loaded.OfType<BlockUIContainer>().Single().Child is System.Windows.Controls.Image,"Nested image missing after reopen");}}finally{app.Store=originalStore;}});
  Check("Imported PNG remains after source file is removed",()=>{string path=Path.Combine(root,"source.png");var enc=new PngBitmapEncoder();enc.Frames.Add(BitmapFrame.Create(BitmapSource.Create(40,20,96,96,PixelFormats.Bgra32,null,Enumerable.Repeat((byte)220,40*20*4).ToArray(),160)));using(var file=File.Create(path))enc.Save(file);window!.AddImageFile(path);Assert(window.Save(),"Save failed");File.Delete(path);var doc=new FlowDocument();app.Store.LoadDocument(note!,doc);Assert(doc.Blocks.OfType<BlockUIContainer>().Count()==2,"Imported image depended on source file");});
  Check("Strong color selection persists with its appearance mode",()=>{note!.Color="#FF00D4";note.ColorMode="Neon";window!.ApplyColor();window.MarkDirty();Assert(window.Save(),"Save failed");var n=new Store(root).Book.Notes.Single();Assert(n.Color=="#FF00D4"&&n.ColorMode=="Neon","Strong color was lost on reopen");var surface=(System.Windows.Controls.Border)window.Content;Assert(((SolidColorBrush)surface.Background).Color==(Color)ColorConverter.ConvertFromString(n.Color),"Actual note surface is muted");});
  Check("Cancelling deletion leaves note, index and images unchanged",()=>{var index=File.ReadAllBytes(Path.Combine(root,"notebook.json"));var document=File.ReadAllBytes(app.Store.DocumentPath(note!));Assert(!app.Store.MoveToTrash(note!,false),"Cancellation accepted as deletion");Assert(!note!.Deleted&&index.SequenceEqual(File.ReadAllBytes(Path.Combine(root,"notebook.json")))&&document.SequenceEqual(File.ReadAllBytes(app.Store.DocumentPath(note))),"Cancellation mutated data");});
  Check("Deletion dialog defaults to cancel, never delete",()=>{new System.Windows.Interop.WindowInteropHelper(window!).EnsureHandle();var dialog=new DeleteConfirmation(window!,"Escuro");var border=(System.Windows.Controls.Border)dialog.Content;var panel=(System.Windows.Controls.StackPanel)border.Child;var buttons=panel.Children.OfType<System.Windows.Controls.StackPanel>().Single().Children.OfType<System.Windows.Controls.Button>().ToList();Assert(buttons.Single(b=>b.IsDefault).IsCancel&&buttons.Single(b=>(string)b.Content=="Excluir nota").IsDefault==false,"Deletion was the default action");dialog.Close();});
  Check("Confirmed deletion and restore retain document",()=>{Assert(app.Store.MoveToTrash(note!,true),"Confirmed deletion failed");Assert(new Store(root).Book.Notes.Single().Deleted,"Archive missing");note!.Deleted=false;app.Store.Save();Assert(File.Exists(app.Store.DocumentPath(note)),"Document lost");});
  Check("Failed deletion write rolls back archive state",()=>{var target=new Store(Path.Combine(root,"archive-failure"));var n=target.Create();var updated=n.Updated;Directory.CreateDirectory(Path.Combine(target.Root,"notebook.json.tmp"));try{target.MoveToTrash(n,true);throw new Exception("Write error ignored");}catch(Exception e) when(e is IOException or UnauthorizedAccessException){Assert(!n.Deleted&&n.Updated==updated&&!new Store(target.Root).Book.Notes.Single().Deleted,"Failed archive changed state");}});
  Check("Document backup recovers corrupt current file",()=>{window!.MarkDirty();Assert(window.Save(),"Save failed");File.WriteAllText(app.Store.DocumentPath(note!),"broken package");var d=new FlowDocument();app.Store.LoadDocument(note!,d);Assert(new TextRange(d.ContentStart,d.ContentEnd).Text.Contains("Texto salvo"),"Backup not recovered");});
  Check("Atomic metadata backup recovers invalid JSON",()=>{app.Store.Save();File.WriteAllText(Path.Combine(root,"notebook.json"),"{broken");var recovered=new Store(root);Assert(recovered.Book.Notes.Count==1&&recovered.RecoveryMessage!=null,"Index backup not recovered");});
  Check("Invalid index without backup fails without overwrite",()=>{string dir=Path.Combine(root,"invalid");Directory.CreateDirectory(dir);string path=Path.Combine(dir,"notebook.json");File.WriteAllText(path,"broken");try{_ =new Store(dir);throw new Exception("Corruption silently ignored");}catch(InvalidDataException){Assert(File.ReadAllText(path)=="broken","Original overwritten");}});
  Check("Future schema is preserved and rejected even with old backup",()=>{string dir=Path.Combine(root,"future");Directory.CreateDirectory(dir);File.WriteAllText(Path.Combine(dir,"notebook.json"),"{\"Schema\":42}");File.WriteAllText(Path.Combine(dir,"notebook.json.bak"),"{\"Schema\":1}");try{_=new Store(dir);throw new Exception("Future schema accepted");}catch(NotSupportedException){Assert(File.ReadAllText(Path.Combine(dir,"notebook.json"))=="{\"Schema\":42}","Future data overwritten");}});
  Check("Write failure stays dirty and prevents closing",()=>{var blocked=new Store(Path.Combine(root,"blocked"));var n=blocked.Create();var previous=app.Store;app.Store=blocked;var w=new NoteWindow(app,n);app.Store=previous;string dest=previous.DocumentPath(n);Directory.CreateDirectory(dest);w.MarkDirty();Assert(!w.Save(),"Write error ignored");Assert(w.SaveWarningVisible,"Save failure was hidden with the passive status text");w.Conceal();Assert(Directory.Exists(dest),"Test setup unexpectedly mutated");});
  Check("Invalid local color, geometry and duplicate IDs recover backup without overwriting original",()=>{foreach(string kind in new[]{"color","size","duplicate"}){var store=new Store(Path.Combine(root,"invalid-metadata-"+kind));store.Create();store.Create();store.Save();string path=Path.Combine(store.Root,"notebook.json");var json=System.Text.Json.Nodes.JsonNode.Parse(File.ReadAllText(path))!;if(kind=="color")json["Notes"]![0]!["Color"]="bad color";else if(kind=="size")json["Notes"]![0]!["Width"]=-1;else json["Notes"]![1]!["Id"]=json["Notes"]![0]!["Id"]!.GetValue<string>();string malformed=json.ToJsonString();File.WriteAllText(path,malformed);var recovered=new Store(store.Root);Assert(recovered.RecoveryMessage!=null&&File.ReadAllText(path)==malformed&&Directory.GetFiles(store.Root,"*.unreadable-*").Length==1,"Malformed original not preserved: "+kind);}});
  Check("Negative legacy color sequence cannot crash or stall note creation",()=>{Assert(Store.NextColor(-1)==Store.Palette[0],"Invalid color sequence escaped bounds");var colors=new Store(Path.Combine(root,"negative-color-sequence"));colors.Create();colors.Book.ColorSequence=int.MinValue;Assert(colors.Create().Color!=Store.Palette[0],"Negative sequence stalled or repeated a color");});
  Check("Unreadable copied Google session preserves ciphertext and allows a new account",()=>{string dir=Path.Combine(root,"copied-session"),path=Path.Combine(dir,".sync","google-session.dat");Directory.CreateDirectory(Path.GetDirectoryName(path)!);byte[] old={1,2,3,4,5};File.WriteAllBytes(path,old);using(var drive=new GoogleDriveSync(dir,clientIdOverride:"fixture.apps.googleusercontent.com")){Assert(drive.Session==null&&drive.RecoveryMessage!=null&&File.ReadAllBytes(path).SequenceEqual(old),"Copied session was deleted or blocked recovery");drive.Accept(new("fixture-subject","fixture@example.invalid","synthetic-refresh"));}using var reopened=new GoogleDriveSync(dir,clientIdOverride:"fixture.apps.googleusercontent.com");Assert(reopened.Session?.Subject=="fixture-subject"&&File.ReadAllBytes(path+".bak").SequenceEqual(old),"Reconnect did not preserve old encrypted session");});
  Check("Malformed protected Google session is recoverable without losing local data",()=>{foreach(string payload in new[]{"{broken","{}","null"}){string dir=Path.Combine(root,"invalid-session-"+Guid.NewGuid().ToString("N")),path=Path.Combine(dir,".sync","google-session.dat");Directory.CreateDirectory(Path.GetDirectoryName(path)!);var bytes=System.Security.Cryptography.ProtectedData.Protect(System.Text.Encoding.UTF8.GetBytes(payload),null,System.Security.Cryptography.DataProtectionScope.CurrentUser);File.WriteAllBytes(path,bytes);using var drive=new GoogleDriveSync(dir,clientIdOverride:"fixture.apps.googleusercontent.com");Assert(drive.Session==null&&drive.RecoveryMessage!=null&&File.ReadAllBytes(path).SequenceEqual(bytes),"Bad session prevented reconnect or changed original");}});
  SyncTests.Run(root,Check);
  int p=Array.IndexOf(args,"--report");string report=p>=0&&p+1<args.Length?args[p+1]:Path.Combine(root,"report.json");Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(report))!);File.WriteAllText(report,JsonSerializer.Serialize(new{at=DateTimeOffset.Now,version=Distribution.Version,processArchitecture=System.Runtime.InteropServices.RuntimeInformation.ProcessArchitecture.ToString(),osArchitecture=System.Runtime.InteropServices.RuntimeInformation.OSArchitecture.ToString(),packaged=Distribution.IsPackaged,passed=results.Count-failures,failed=failures,root,results},new JsonSerializerOptions{WriteIndented=true}));return failures==0?0:1;
 }
}
